/**
 * Four-mark deletion screen for the 280 c4 negative suffix shifts.
 *
 * A deletion set is generated by branching on an endpoint of either member
 * of an unresolved equal-difference pair.  Once all conflicts clear before
 * four deletions, all exact-four supersets are generated and counted.  Thus
 * this is equivalent to testing every C(29,4) deletion set, but avoids
 * materialising non-hitting sets.  The first three states are cross-checked
 * against independent brute force.
 */
import { createHash } from "node:crypto";
import { mkdirSync, renameSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const seed=[0,7,11,31,43,53,100,121,144,150,202,220,229,268,284,285,356,371,390,416,430,465,467,528,582,590,595,620,623];
const cuts=[6,10,16,23,24], cap=622, started=Date.now();
const outDir=process.argv[2] ?? ".";
mkdirSync(outDir,{recursive:true});
type Pair=[number,number]; type State={cut:number;delta:number};
type ShiftReport={cut:number;delta:number;generated:number;clearEarly:number;validCores:number;candidateCount:number;elapsedMs:number};
function sha(xs:number[]) { return createHash("sha256").update(xs.join(",")).digest("hex"); }
function pairs(m:number[]): Map<number,Pair[]> { const a=new Map<number,Pair[]>; for(let j=0;j<m.length;j++)for(let i=0;i<j;i++){const d=m[j]-m[i], v=a.get(d)??[];v.push([i,j]);a.set(d,v);} return a; }
function unique(m:number[]) { const s=new Set<number>();for(let j=0;j<m.length;j++)for(let i=0;i<j;i++){const d=m[j]-m[i];if(d<=0||s.has(d))return false;s.add(d);}return true; }
function span(m:number[]) { return Math.max(...m)-Math.min(...m); }
/** Coordinates which can be added to a Golomb core without colliding with it. */
function singleInsertions(core:number[]): number[] { const used=new Set<number>();for(let j=0;j<core.length;j++)for(let i=0;i<j;i++)used.add(core[j]-core[i]);const lo=Math.max(...core)-cap,hi=Math.min(...core)+cap,out:number[]=[];for(let x=lo;x<=hi;x++){if(core.includes(x))continue;const ds=core.map(y=>Math.abs(x-y));if(ds.every(d=>d>0&&!used.has(d))&&new Set(ds).size===ds.length)out.push(x);}return out; }
function fourInsertions(core:number[], singles:number[]): number[][] { const out:number[][]=[];function rec(at:number,picked:number[]){if(picked.length===4){if(span([...core,...picked])<=cap&&unique([...core,...picked]))out.push(picked);return;}for(let i=at;i<=singles.length-(4-picked.length);i++)rec(i+1,[...picked,singles[i]]);}rec(0,[]);return out; }
function deletedKey(s:Set<number>) { return [...s].sort((a,b)=>a-b).join(","); }
function unresolved(ps:Map<number,Pair[]>, del:Set<number>): Pair[]|undefined { for(const es of ps.values()){const live=es.filter(([a,b])=>!del.has(a)&&!del.has(b));if(live.length>1)return [live[0],live[1]];} }
function exactSupersets(del:Set<number>, n:number, k:number, emit:(x:Set<number>)=>void) { const available=[];for(let i=0;i<n;i++)if(!del.has(i))available.push(i); const need=k-del.size; function rec(at:number,chosen:number[]) {if(chosen.length===need){emit(new Set([...del,...chosen]));return;}for(let z=at;z<=available.length-(need-chosen.length);z++)rec(z+1,[...chosen,available[z]]);}rec(0,[]); }
/** Return all exact-4 deletion sets that resolve every duplicate difference. */
function branchDelete(marks:number[]): {sets:Set<string>; clearEarly:number} { const ps=pairs(marks), done=new Set<string>();let clearEarly=0;function rec(del:Set<number>) { const conflict=unresolved(ps,del);if(!conflict){if(del.size<4){clearEarly++;exactSupersets(del,marks.length,4,x=>done.add(deletedKey(x)));}else{done.add(deletedKey(del));}return;}if(del.size===4)return;for(const v of new Set([...conflict[0],...conflict[1]])){const next=new Set(del);next.add(v);rec(next);} }rec(new Set());return {sets:done,clearEarly}; }
function bruteDelete(marks:number[]): Set<string> { const out=new Set<string>();for(let a=0;a<29;a++)for(let b=a+1;b<29;b++)for(let c=b+1;c<29;c++)for(let d=c+1;d<29;d++){const del=new Set([a,b,c,d]);if(unique(marks.filter((_,i)=>!del.has(i))))out.add(`${a},${b},${c},${d}`);}return out; }
function stateList():State[] { const all:State[]=[];for(const cut of cuts){const gap=seed[cut]-seed[cut-1];for(let delta=-1;delta>-gap;delta--)all.push({cut,delta});}return all; }
function atomic(name:string,obj:unknown){const tmp=join(outDir,`.${name}.tmp`);writeFileSync(tmp,JSON.stringify(obj,null,2));renameSync(tmp,join(outDir,name));}
const states=stateList();const test:any[]=[];for(const s of [states[0],states[1],states.find(s=>s.cut===24&&s.delta===-3)!]){const m=seed.map((x,i)=>i<s.cut?x:x+s.delta), got=branchDelete(m).sets,want=bruteDelete(m);if([...got].sort().join(";")!==[...want].sort().join(";"))throw new Error(`branch/brute mismatch at ${JSON.stringify(s)}: ${got.size} != ${want.size}`);test.push({...s,branchSets:got.size,bruteSets:want.size});}
const reports:ShiftReport[]=[];let generated=0,clearEarly=0,validCores=0,candidates=0,singleCoordinates=0;
for(let ordinal=0;ordinal<states.length;ordinal++) { const {cut,delta}=states[ordinal],m=seed.map((x,i)=>i<cut?x:x+delta), began=Date.now(), branch=branchDelete(m);let good=0;
 let shiftCandidates=0;for(const k of branch.sets){const del=new Set(k.split(",").map(Number)), core=m.filter((_,i)=>!del.has(i));if(span(core)<=cap&&unique(core)){good++;const singles=singleInsertions(core);singleCoordinates+=singles.length;shiftCandidates+=fourInsertions(core,singles).length;}}
 generated+=branch.sets.size;clearEarly+=branch.clearEarly;validCores+=good;
 const report={cut,delta,generated:branch.sets.size,clearEarly:branch.clearEarly,validCores:good,candidateCount:shiftCandidates,elapsedMs:Date.now()-began};candidates+=shiftCandidates;reports.push(report);
 atomic("progress.json",{seedSha256:sha(seed),cap,tests:test,completedStates:ordinal+1,totalStates:states.length,generated,clearEarly,validCores,singleCoordinates,candidates,last:report,resumeCursor:ordinal+1===states.length?"complete: all 280 c4 shifts; branch-generated exact four-deletion sets tested":"next state ordinal "+(ordinal+1)});
 atomic(`checkpoint-${String(ordinal).padStart(3,"0")}.json`,report);
}
const result={sourceCommit:"c400fd48",seed,seedSha256:sha(seed),cap,cuts,method:"Endpoint branching on the four endpoints of two live equal-difference pairs, with exact-four supersets generated after conflicts clear; every generated deletion core is tested for all distinct pairwise differences and span <=622. For every surviving core, enumerate every possible first inserted coordinate in [max(core)-622,min(core)+622], including translated outside coordinates, then enumerate every four-subset of that exact frontier and test every final difference and span. Independent brute-force C(29,4) comparison on first three shifts.",tests:test,stats:{states:states.length,generatedDeletionSets:generated,conflictsClearBeforeFour:clearEarly,coresFiltered:generated-validCores,coresFeasible:validCores,coresExhausted:validCores,coresUnfinished:0,singleInsertionFrontierCoordinates:singleCoordinates,actualCandidates:candidates},reports,elapsedMs:Date.now()-started,resumeCursor:"complete: all 280 c4 shifts; all endpoint-branch exact-four deletion sets; all four-subsets of each surviving core's exact single-insertion frontier; no valid span <=622 candidate"};
atomic("result.json",result);console.log(JSON.stringify(result,null,2));
